import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getApiBase } from "../api/base";
import { authFetch } from "../api/authFetch";
import {
  Building2,
  Users,
  Store,
  Package,
  ArrowLeft,
  Edit2,
  Save,
  X,
  RefreshCcw,
} from "lucide-react";

const API = getApiBase() + "/backend";

export default function SuperAdminPharmacyDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState("overview");
  // Drilldown data states
  const [usersData, setUsersData] = useState({
    loading: false,
    error: null,
    items: [],
    loaded: false,
  });
  const [userCreate, setUserCreate] = useState({
    username: "",
    email: "",
    password: "",
    role: "employee",
    branch: "",
    error: null,
    saving: false,
  });
  const [branchesData, setBranchesData] = useState({
    loading: false,
    error: null,
    items: [],
    loaded: false,
  });
  const [branchCreate, setBranchCreate] = useState({
    name: "",
    address: "",
    error: null,
    saving: false,
  });
  const [medicinesData, setMedicinesData] = useState({
    loading: false,
    error: null,
    items: [],
    loaded: false,
  });
  const [requestsData, setRequestsData] = useState({
    loading: false,
    error: null,
    items: [],
    loaded: false,
  });
  const [transactionsData, setTransactionsData] = useState({
    loading: false,
    error: null,
    items: [],
    loaded: false,
  });
  // Export UI state
  const [exporting, setExporting] = useState(false);
  const [exportTypes, setExportTypes] = useState({
    users: true,
    medicines: false,
    transactions: false,
    branch_medicines: false,
  });
  const [exportBranch, setExportBranch] = useState("");
  const [exportFormat, setExportFormat] = useState("xlsx");
  // Inline user edit state
  const [editingUserId, setEditingUserId] = useState(null);
  const [editUserValues, setEditUserValues] = useState({
    username: "",
    email: "",
    role: "employee",
    branch: "",
    password: "",
    saving: false,
    error: null,
  });
  // Inline branch edit state
  const [editingBranchId, setEditingBranchId] = useState(null);
  const [editBranchValues, setEditBranchValues] = useState({
    name: "",
    address: "",
    saving: false,
    error: null,
  });
  // Inline edit state
  const [editing, setEditing] = useState(false);
  const [editValues, setEditValues] = useState({
    name: "",
    address: "",
    status: "ACTIVE",
  });
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await authFetch(`${API}/superadmin/pharmacies/${id}`);
        const txt = await res.text();
        let json;
        try {
          json = JSON.parse(txt);
        } catch {
          throw new Error("Non-JSON response");
        }
        if (!res.ok || !json.success)
          throw new Error(json.message || "Load failed");
        setData(json);
      } catch (e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [id]);

  // When switching tabs, fetch data if not already fetched
  useEffect(() => {
    if (!id) return;
    const fetcher = async (url, setState) => {
      setState((s) => ({ ...s, loading: true, error: null }));
      try {
        const res = await authFetch(url);
        const txt = await res.text();
        let json;
        try {
          json = JSON.parse(txt);
        } catch {
          throw new Error("Non-JSON response");
        }
        if (!res.ok || !json.success)
          throw new Error(json.message || "Load failed");
        const key = Object.keys(json).find((k) => Array.isArray(json[k]));
        const items = key ? json[key] : [];
        setState({ loading: false, error: null, items, loaded: true });
      } catch (e) {
        setState({ loading: false, error: e.message, items: [], loaded: true });
      }
    };
    if (activeTab === "users" && !usersData.loaded && !usersData.loading) {
      fetcher(`${API}/superadmin/pharmacies/${id}/users`, setUsersData);
    } else if (
      activeTab === "branches" &&
      !branchesData.loaded &&
      !branchesData.loading
    ) {
      fetcher(`${API}/superadmin/pharmacies/${id}/branches`, setBranchesData);
    } else if (
      activeTab === "medicines" &&
      !medicinesData.loaded &&
      !medicinesData.loading
    ) {
      fetcher(
        `${API}/superadmin/pharmacies/${id}/medicines?includeDeleted=false`,
        setMedicinesData
      );
    } else if (
      activeTab === "requests" &&
      !requestsData.loaded &&
      !requestsData.loading
    ) {
      fetcher(`${API}/superadmin/pharmacies/${id}/requests`, setRequestsData);
    } else if (
      activeTab === "transactions" &&
      !transactionsData.loaded &&
      !transactionsData.loading
    ) {
      fetcher(
        `${API}/superadmin/pharmacies/${id}/transactions`,
        setTransactionsData
      );
    }
  }, [
    activeTab,
    id,
    usersData.loaded,
    usersData.loading,
    branchesData.loaded,
    branchesData.loading,
    medicinesData.loaded,
    medicinesData.loading,
    requestsData.loaded,
    requestsData.loading,
    transactionsData.loaded,
    transactionsData.loading,
  ]);

  // Begin editing when user clicks edit icon
  const beginEdit = () => {
    if (!pharmacy) return;
    setEditValues({
      name: pharmacy.name,
      address: pharmacy.address || "",
      status: pharmacy.status || "ACTIVE",
    });
    setEditing(true);
    setSaveError(null);
  };
  const cancelEdit = () => {
    setEditing(false);
    setSaveError(null);
  };
  const saveEdit = async () => {
    setSaving(true);
    setSaveError(null);
    try {
      const res = await authFetch(`${API}/superadmin/pharmacies/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editValues),
      });
      const txt = await res.text();
      let json;
      try {
        json = JSON.parse(txt);
      } catch {
        throw new Error("Non-JSON response");
      }
      if (!res.ok || !json.success)
        throw new Error(json.message || "Save failed");
      // Refresh summary
      setData((d) => (d ? { ...d, pharmacy: json.pharmacy } : d));
      setEditing(false);
    } catch (e) {
      setSaveError(e.message);
    } finally {
      setSaving(false);
    }
  };

  const summary = data?.summary || {};
  const pharmacy = data?.pharmacy;
  const roleCounts = summary.users || {};
  const reqCounts = summary.requests || {};

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 text-sm text-white/50 flex-wrap">
        <button
          onClick={() => navigate("/admin")}
          className="hover:text-white transition"
        >
          Admin
        </button>
        <span>/</span>
        <button
          onClick={() => navigate("/admin")}
          className="hover:text-white transition"
        >
          Pharmacies
        </button>
        <span>/</span>
        <span className="text-white/80">{pharmacy?.name || "..."}</span>
      </div>
      <div className="flex items-center gap-4 flex-wrap">
        <div className="flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="px-3 py-2 rounded bg-white/10 hover:bg-white/20 inline-flex items-center gap-2 text-sm"
          >
            <ArrowLeft className="w-4 h-4" /> Back
          </button>
          <div className="flex items-center gap-2">
            <Building2 className="w-6 h-6 text-indigo-300" />
            {!editing && (
              <h1 className="text-2xl font-bold tracking-tight">
                {pharmacy?.name || "..."}
              </h1>
            )}
            {editing && (
              <input
                value={editValues.name}
                onChange={(e) =>
                  setEditValues((v) => ({ ...v, name: e.target.value }))
                }
                className="px-2 py-1 rounded bg-white/10 border border-white/20 text-sm"
              />
            )}
            {pharmacy && !editing && (
              <button
                onClick={beginEdit}
                className="p-2 rounded hover:bg-white/10"
                title="Edit pharmacy"
              >
                <Edit2 className="w-4 h-4" />
              </button>
            )}
          </div>
          {pharmacy && !editing && (
            <span className="px-2 py-1 rounded bg-white/10 border border-white/10 text-[11px] font-semibold uppercase">
              {pharmacy.status}
            </span>
          )}
          {editing && (
            <select
              value={editValues.status}
              onChange={(e) =>
                setEditValues((v) => ({ ...v, status: e.target.value }))
              }
              className="px-2 py-1 rounded bg-white/10 border border-white/20 text-xs"
            >
              <option value="ACTIVE">ACTIVE</option>
              <option value="SUSPENDED">SUSPENDED</option>
            </select>
          )}
        </div>
        <div className="flex items-center gap-2">
          {editing && (
            <>
              <button
                onClick={saveEdit}
                disabled={saving}
                className="px-3 py-2 rounded bg-[var(--brand)] text-white text-xs inline-flex items-center gap-2"
              >
                <Save className="w-4 h-4" /> {saving ? "Saving..." : "Save"}
              </button>
              <button
                onClick={cancelEdit}
                className="px-3 py-2 rounded bg-white/10 hover:bg-white/20 text-xs inline-flex items-center gap-2"
              >
                <X className="w-4 h-4" /> Cancel
              </button>
            </>
          )}
          {!editing && (
            <button
              onClick={() => {
                // refresh
                setData(null);
                setLoading(true);
                authFetch(`${API}/superadmin/pharmacies/${id}`)
                  .then((r) => r.text())
                  .then((t) => {
                    try {
                      const j = JSON.parse(t);
                      if (j.success) setData(j);
                    } catch {
                      /* ignore parse */
                    }
                  })
                  .finally(() => setLoading(false));
              }}
              className="px-3 py-2 rounded bg-white/10 hover:bg-white/20 text-xs inline-flex items-center gap-2"
            >
              <RefreshCcw className="w-4 h-4" /> Refresh
            </button>
          )}
        </div>
      </div>
      {editing && (
        <div className="flex flex-col gap-2 max-w-xl">
          <textarea
            value={editValues.address}
            onChange={(e) =>
              setEditValues((v) => ({ ...v, address: e.target.value }))
            }
            placeholder="Address"
            className="w-full px-3 py-2 rounded bg-white/10 border border-white/20 text-sm"
            rows={2}
          />
          {saveError && (
            <div className="text-rose-400 text-xs">{saveError}</div>
          )}
        </div>
      )}
      {error && (
        <div className="p-3 rounded bg-rose-500/15 border border-rose-500/30 text-sm text-rose-200">
          {error}
        </div>
      )}
      {loading && <div className="text-white/60 text-sm">Loading...</div>}
      {pharmacy && !loading && (
        <>
          <div className="flex items-center gap-2 text-sm flex-wrap">
            <TabButton
              active={activeTab === "overview"}
              onClick={() => setActiveTab("overview")}
            >
              Overview
            </TabButton>
            <TabButton
              active={activeTab === "users"}
              onClick={() => setActiveTab("users")}
            >
              Users
            </TabButton>
            <TabButton
              active={activeTab === "branches"}
              onClick={() => setActiveTab("branches")}
            >
              Branches
            </TabButton>
            <TabButton
              active={activeTab === "medicines"}
              onClick={() => setActiveTab("medicines")}
            >
              Medicines
            </TabButton>
            <TabButton
              active={activeTab === "requests"}
              onClick={() => setActiveTab("requests")}
            >
              Requests
            </TabButton>
            <TabButton
              active={activeTab === "transactions"}
              onClick={() => setActiveTab("transactions")}
            >
              Transactions
            </TabButton>
            <TabButton
              active={activeTab === "export"}
              onClick={() => setActiveTab("export")}
            >
              Export
            </TabButton>
          </div>
          {activeTab === "overview" && (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mt-4">
              <BigStat
                label="Admins"
                value={roleCounts.admin || 0}
                icon={<Users className="w-5 h-5" />}
                onClick={() => setActiveTab("users")}
              />
              <BigStat
                label="Employees"
                value={
                  (roleCounts.employee || 0) +
                  (roleCounts.inventory_manager || 0)
                }
                icon={<Users className="w-5 h-5" />}
                onClick={() => setActiveTab("users")}
              />
              <BigStat
                label="Branches"
                value={summary.branches || 0}
                icon={<Store className="w-5 h-5" />}
                onClick={() => setActiveTab("branches")}
              />
              <BigStat
                label="Medicines"
                value={summary.medicines?.total || 0}
                icon={<Package className="w-5 h-5" />}
                onClick={() => setActiveTab("medicines")}
              />
              <BigStat
                label="Expired"
                value={summary.medicines?.expired || 0}
                icon={<Package className="w-5 h-5" />}
                onClick={() => setActiveTab("medicines")}
              />
              <BigStat
                label="Pending Requests"
                value={reqCounts.Pending || 0}
                icon={<Package className="w-5 h-5" />}
                onClick={() => setActiveTab("requests")}
              />
              <BigStat
                label="Transactions"
                value={summary.transactions || 0}
                icon={<Package className="w-5 h-5" />}
                onClick={() => setActiveTab("transactions")}
              />
            </div>
          )}
          {activeTab === "users" && (
            <div className="mt-6 space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-semibold">Users</h2>
              </div>
              {/* Create user form */}
              <form
                onSubmit={async (e) => {
                  e.preventDefault();
                  setUserCreate((s) => ({ ...s, saving: true, error: null }));
                  try {
                    const res = await authFetch(
                      `${API}/superadmin/pharmacies/${id}/users`,
                      {
                        method: "POST",
                        headers: {
                          "Content-Type": "application/json",
                        },
                        body: JSON.stringify({
                          username: userCreate.username,
                          email: userCreate.email,
                          password: userCreate.password,
                          role: userCreate.role,
                          branch: userCreate.branch || undefined,
                        }),
                      }
                    );
                    const json = await res.json().catch(() => ({}));
                    if (!res.ok || !json.success) {
                      throw new Error(json.message || `HTTP ${res.status}`);
                    }
                    // reset and refresh list
                    setUserCreate({
                      username: "",
                      email: "",
                      password: "",
                      role: "employee",
                      branch: "",
                      error: null,
                      saving: false,
                    });
                    // force one-time refetch users
                    setUsersData((s) => ({ ...s, items: [], loaded: false }));
                    const res2 = await authFetch(
                      `${API}/superadmin/pharmacies/${id}/users`,
                      {}
                    );
                    const j2 = await res2.json().catch(() => ({}));
                    if (j2.success) {
                      setUsersData({
                        loading: false,
                        error: null,
                        items: j2.users || [],
                        loaded: true,
                      });
                    }
                  } catch (err) {
                    setUserCreate((s) => ({ ...s, error: err.message }));
                  } finally {
                    setUserCreate((s) => ({ ...s, saving: false }));
                  }
                }}
                className="grid md:grid-cols-6 gap-3 text-xs md:text-sm"
              >
                <input
                  placeholder="Username"
                  value={userCreate.username}
                  onChange={(e) =>
                    setUserCreate((s) => ({ ...s, username: e.target.value }))
                  }
                  required
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                />
                <input
                  type="email"
                  placeholder="Email"
                  value={userCreate.email}
                  onChange={(e) =>
                    setUserCreate((s) => ({ ...s, email: e.target.value }))
                  }
                  required
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                />
                <input
                  type="password"
                  placeholder="Password"
                  value={userCreate.password}
                  onChange={(e) =>
                    setUserCreate((s) => ({ ...s, password: e.target.value }))
                  }
                  required
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                />
                <select
                  value={userCreate.role}
                  onChange={(e) =>
                    setUserCreate((s) => ({
                      ...s,
                      role: e.target.value,
                      // admins are pharmacy-level; clear branch if switching to admin
                      branch: e.target.value === "admin" ? "" : s.branch,
                    }))
                  }
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                >
                  <option value="employee">Employee</option>
                  <option value="admin">Admin</option>
                </select>
                <select
                  value={userCreate.branch}
                  onChange={(e) =>
                    setUserCreate((s) => ({ ...s, branch: e.target.value }))
                  }
                  disabled={userCreate.role === "admin"}
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                >
                  <option value="">No branch</option>
                  {branchesData.items.map((b) => (
                    <option key={b._id} value={b._id}>
                      {b.name}
                    </option>
                  ))}
                </select>
                <button
                  className="px-3 py-1.5 rounded bg-[var(--brand)] text-white font-semibold disabled:opacity-60"
                  disabled={userCreate.saving}
                >
                  {userCreate.saving ? "Saving..." : "Add User"}
                </button>
                {userCreate.error && (
                  <div className="col-span-full text-rose-400 text-xs">
                    {userCreate.error}
                  </div>
                )}
              </form>
              <div className="overflow-auto rounded-lg border border-white/10">
                <table className="min-w-full text-sm">
                  <thead className="bg-white/5 text-white/60">
                    <tr>
                      {["Username", "Email", "Role", "Branch", "Actions"].map(
                        (c) => (
                          <th
                            key={c}
                            className="text-left px-3 py-2 font-medium uppercase text-[11px]"
                          >
                            {c}
                          </th>
                        )
                      )}
                    </tr>
                  </thead>
                  <tbody>
                    {usersData.items.map((u) => (
                      <tr
                        key={u._id}
                        className="odd:bg-white/0 even:bg-white/[0.015] hover:bg-white/10 transition"
                      >
                        {editingUserId === u._id ? (
                          <>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <input
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                value={editUserValues.username}
                                onChange={(e) =>
                                  setEditUserValues((v) => ({
                                    ...v,
                                    username: e.target.value,
                                  }))
                                }
                              />
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <input
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                value={editUserValues.email}
                                onChange={(e) =>
                                  setEditUserValues((v) => ({
                                    ...v,
                                    email: e.target.value,
                                  }))
                                }
                              />
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <select
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                value={editUserValues.role}
                                onChange={(e) =>
                                  setEditUserValues((v) => ({
                                    ...v,
                                    role: e.target.value,
                                    branch:
                                      e.target.value === "admin"
                                        ? ""
                                        : v.branch,
                                  }))
                                }
                              >
                                <option value="employee">Employee</option>
                                <option value="admin">Admin</option>
                              </select>
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <select
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                disabled={editUserValues.role === "admin"}
                                value={editUserValues.branch}
                                onChange={(e) =>
                                  setEditUserValues((v) => ({
                                    ...v,
                                    branch: e.target.value,
                                  }))
                                }
                              >
                                <option value="">No branch</option>
                                {branchesData.items.map((b) => (
                                  <option key={b._id} value={b._id}>
                                    {b.name}
                                  </option>
                                ))}
                              </select>
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <div className="flex gap-2">
                                <button
                                  className="px-2 py-1 text-xs rounded bg-[var(--brand)]/80 text-white"
                                  disabled={editUserValues.saving}
                                  onClick={async () => {
                                    setEditUserValues((v) => ({
                                      ...v,
                                      saving: true,
                                      error: null,
                                    }));
                                    const body = {
                                      username: editUserValues.username,
                                      email: editUserValues.email,
                                      role: editUserValues.role,
                                    };
                                    if (editUserValues.branch)
                                      body.branch = editUserValues.branch;
                                    if (editUserValues.password)
                                      body.password = editUserValues.password;
                                    const res = await authFetch(
                                      `${API}/superadmin/pharmacies/${id}/users/${u._id}`,
                                      {
                                        method: "PATCH",
                                        headers: {
                                          "Content-Type": "application/json",
                                        },
                                        body: JSON.stringify(body),
                                      }
                                    );
                                    const j = await res
                                      .json()
                                      .catch(() => ({}));
                                    setEditUserValues((v) => ({
                                      ...v,
                                      saving: false,
                                    }));
                                    if (j.success) {
                                      setUsersData((s) => ({
                                        ...s,
                                        items: s.items.map((x) =>
                                          x._id === u._id ? j.user : x
                                        ),
                                      }));
                                      setEditingUserId(null);
                                    } else {
                                      setEditUserValues((v) => ({
                                        ...v,
                                        error:
                                          j.message || `HTTP ${res.status}`,
                                      }));
                                    }
                                  }}
                                >
                                  Save
                                </button>
                                <button
                                  className="px-2 py-1 text-xs rounded bg-white/10 hover:bg-white/20"
                                  onClick={() => setEditingUserId(null)}
                                >
                                  Cancel
                                </button>
                              </div>
                              {editUserValues.error && (
                                <div className="text-rose-400 text-[10px]">
                                  {editUserValues.error}
                                </div>
                              )}
                            </td>
                          </>
                        ) : (
                          <>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {u.username}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {u.email}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {u.role}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {u.branch?.name || "—"}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <div className="flex gap-2">
                                <button
                                  className="px-2 py-1 text-xs rounded bg-white/10 hover:bg-white/20"
                                  onClick={() => {
                                    setEditingUserId(u._id);
                                    setEditUserValues({
                                      username: u.username || "",
                                      email: u.email || "",
                                      role: u.role || "employee",
                                      branch: u.branch?._id || "",
                                      password: "",
                                      saving: false,
                                      error: null,
                                    });
                                  }}
                                >
                                  Edit
                                </button>
                                <button
                                  className="px-2 py-1 text-xs rounded bg-rose-500/20 hover:bg-rose-500/30"
                                  onClick={async () => {
                                    if (!confirm("Delete this user?")) return;
                                    const res = await authFetch(
                                      `${API}/superadmin/pharmacies/${id}/users/${u._id}`,
                                      {
                                        method: "DELETE",
                                        headers: {},
                                      }
                                    );
                                    const j = await res
                                      .json()
                                      .catch(() => ({}));
                                    if (j.success) {
                                      setUsersData((s) => ({
                                        ...s,
                                        items: s.items.filter(
                                          (x) => x._id !== u._id
                                        ),
                                      }));
                                    }
                                  }}
                                >
                                  Delete
                                </button>
                              </div>
                            </td>
                          </>
                        )}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          {activeTab === "branches" && (
            <div className="mt-6 space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-semibold">Branches</h2>
              </div>
              {/* Create branch form */}
              <form
                onSubmit={async (e) => {
                  e.preventDefault();
                  setBranchCreate((s) => ({ ...s, saving: true, error: null }));
                  try {
                    const res = await authFetch(
                      `${API}/superadmin/pharmacies/${id}/branches`,
                      {
                        method: "POST",
                        headers: {
                          "Content-Type": "application/json",
                        },
                        body: JSON.stringify({
                          name: branchCreate.name,
                          address: branchCreate.address,
                        }),
                      }
                    );
                    const json = await res.json().catch(() => ({}));
                    if (!res.ok || !json.success) {
                      throw new Error(json.message || `HTTP ${res.status}`);
                    }
                    setBranchCreate({
                      name: "",
                      address: "",
                      error: null,
                      saving: false,
                    });
                    // force refetch branches
                    const res2 = await authFetch(
                      `${API}/superadmin/pharmacies/${id}/branches`,
                      {}
                    );
                    const j2 = await res2.json().catch(() => ({}));
                    if (j2.success) {
                      setBranchesData({
                        loading: false,
                        error: null,
                        items: j2.branches || [],
                      });
                    }
                  } catch (err) {
                    setBranchCreate((s) => ({ ...s, error: err.message }));
                  } finally {
                    setBranchCreate((s) => ({ ...s, saving: false }));
                  }
                }}
                className="grid md:grid-cols-4 gap-3 text-xs md:text-sm"
              >
                <input
                  placeholder="Branch name"
                  value={branchCreate.name}
                  onChange={(e) =>
                    setBranchCreate((s) => ({ ...s, name: e.target.value }))
                  }
                  required
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                />
                <input
                  placeholder="Address"
                  value={branchCreate.address}
                  onChange={(e) =>
                    setBranchCreate((s) => ({ ...s, address: e.target.value }))
                  }
                  className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
                />
                <button
                  className="px-3 py-1.5 rounded bg-[var(--brand)] text-white font-semibold disabled:opacity-60"
                  disabled={branchCreate.saving}
                >
                  {branchCreate.saving ? "Saving..." : "Add Branch"}
                </button>
                {branchCreate.error && (
                  <div className="col-span-full text-rose-400 text-xs">
                    {branchCreate.error}
                  </div>
                )}
              </form>
              <div className="overflow-auto rounded-lg border border-white/10">
                <table className="min-w-full text-sm">
                  <thead className="bg-white/5 text-white/60">
                    <tr>
                      {["Name", "Address", "Created", "Actions"].map((c) => (
                        <th
                          key={c}
                          className="text-left px-3 py-2 font-medium uppercase text-[11px]"
                        >
                          {c}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {branchesData.items.map((b) => (
                      <tr
                        key={b._id}
                        className="odd:bg-white/0 even:bg-white/[0.015] hover:bg-white/10 transition"
                      >
                        {editingBranchId === b._id ? (
                          <>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <input
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                value={editBranchValues.name}
                                onChange={(e) =>
                                  setEditBranchValues((v) => ({
                                    ...v,
                                    name: e.target.value,
                                  }))
                                }
                              />
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <input
                                className="px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                                value={editBranchValues.address}
                                onChange={(e) =>
                                  setEditBranchValues((v) => ({
                                    ...v,
                                    address: e.target.value,
                                  }))
                                }
                              />
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {new Date(b.createdAt).toLocaleDateString()}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <div className="flex gap-2">
                                <button
                                  className="px-2 py-1 text-xs rounded bg-[var(--brand)]/80 text-white"
                                  disabled={editBranchValues.saving}
                                  onClick={async () => {
                                    setEditBranchValues((v) => ({
                                      ...v,
                                      saving: true,
                                      error: null,
                                    }));
                                    const res = await authFetch(
                                      `${API}/superadmin/pharmacies/${id}/branches/${b._id}`,
                                      {
                                        method: "PATCH",
                                        headers: {
                                          "Content-Type": "application/json",
                                        },
                                        body: JSON.stringify({
                                          name: editBranchValues.name,
                                          address: editBranchValues.address,
                                        }),
                                      }
                                    );
                                    const j = await res
                                      .json()
                                      .catch(() => ({}));
                                    setEditBranchValues((v) => ({
                                      ...v,
                                      saving: false,
                                    }));
                                    if (j.success) {
                                      setBranchesData((s) => ({
                                        ...s,
                                        items: s.items.map((x) =>
                                          x._id === b._id ? j.branch : x
                                        ),
                                      }));
                                      setEditingBranchId(null);
                                    } else {
                                      setEditBranchValues((v) => ({
                                        ...v,
                                        error:
                                          j.message || `HTTP ${res.status}`,
                                      }));
                                    }
                                  }}
                                >
                                  Save
                                </button>
                                <button
                                  className="px-2 py-1 text-xs rounded bg-white/10 hover:bg-white/20"
                                  onClick={() => setEditingBranchId(null)}
                                >
                                  Cancel
                                </button>
                              </div>
                              {editBranchValues.error && (
                                <div className="text-rose-400 text-[10px]">
                                  {editBranchValues.error}
                                </div>
                              )}
                            </td>
                          </>
                        ) : (
                          <>
                            <td
                              className="px-3 py-2 whitespace-nowrap cursor-pointer"
                              onClick={() =>
                                navigate(
                                  `/admin/pharmacies/${id}/branches/${b._id}`
                                )
                              }
                            >
                              {b.name}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {b.address || "—"}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              {new Date(b.createdAt).toLocaleDateString()}
                            </td>
                            <td className="px-3 py-2 whitespace-nowrap">
                              <div className="flex gap-2">
                                <button
                                  className="px-2 py-1 text-xs rounded bg-white/10 hover:bg-white/20"
                                  onClick={() => {
                                    setEditingBranchId(b._id);
                                    setEditBranchValues({
                                      name: b.name || "",
                                      address: b.address || "",
                                      saving: false,
                                      error: null,
                                    });
                                  }}
                                >
                                  Edit
                                </button>
                                <button
                                  className="px-2 py-1 text-xs rounded bg-rose-500/20 hover:bg-rose-500/30"
                                  onClick={async () => {
                                    if (!confirm("Delete branch?")) return;
                                    const res = await authFetch(
                                      `${API}/superadmin/pharmacies/${id}/branches/${b._id}`,
                                      {
                                        method: "DELETE",
                                        headers: {},
                                      }
                                    );
                                    const j = await res
                                      .json()
                                      .catch(() => ({}));
                                    if (j.success) {
                                      setBranchesData((s) => ({
                                        ...s,
                                        items: s.items.filter(
                                          (x) => x._id !== b._id
                                        ),
                                      }));
                                    }
                                  }}
                                >
                                  Delete
                                </button>
                              </div>
                            </td>
                          </>
                        )}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          {activeTab === "medicines" && (
            <DrillList
              title="Medicines"
              state={medicinesData}
              columns={[
                "Name",
                "Category",
                "Batch",
                "Expiry",
                "Qty",
                "Deleted",
              ]}
              rows={medicinesData.items.map((m) => {
                const qty =
                  m.remainingQuantity ??
                  m.initialQuantity ??
                  m.liveQuantity ??
                  m.centralNetQuantity ??
                  m.quantity ??
                  0;
                return [
                  m.medicineName,
                  m.category,
                  m.batchNumber,
                  new Date(m.expiryDate).toLocaleDateString(),
                  qty,
                  m.isDeleted ? "Yes" : "No",
                ];
              })}
            />
          )}
          {activeTab === "requests" && (
            <DrillList
              title="Requests"
              state={requestsData}
              columns={["Medicine", "Branch", "Qty", "Status", "Created"]}
              rows={requestsData.items.map((r) => [
                r.medicine?.medicineName || "—",
                r.branch?.name || "—",
                r.quantity,
                r.status,
                new Date(r.createdAt).toLocaleString(),
              ])}
            />
          )}
          {activeTab === "transactions" && (
            <DrillList
              title="Transactions"
              state={transactionsData}
              columns={["Date", "Branch", "Medicine", "Qty", "Type", "Status"]}
              rows={transactionsData.items.map((t) => [
                new Date(t.createdAt).toLocaleString(),
                t.branch,
                t.medicine,
                t.qty,
                t.type,
                t.status,
              ])}
            />
          )}
          {activeTab === "export" && (
            <div className="mt-6 space-y-4">
              <h2 className="text-lg font-semibold">Export Data</h2>
              <div className="grid md:grid-cols-3 gap-4">
                <div className="space-y-2">
                  <div className="text-xs uppercase font-semibold text-white/60">
                    Types
                  </div>
                  {[
                    { key: "users", label: "Users" },
                    { key: "medicines", label: "Medicines" },
                    { key: "transactions", label: "Transactions" },
                    { key: "branch_medicines", label: "Branch Medicines" },
                  ].map(({ key, label }) => (
                    <label
                      key={key}
                      className="flex items-center gap-2 text-sm"
                    >
                      <input
                        type="checkbox"
                        checked={!!exportTypes[key]}
                        onChange={(e) =>
                          setExportTypes((s) => ({
                            ...s,
                            [key]: e.target.checked,
                          }))
                        }
                      />
                      <span>{label}</span>
                    </label>
                  ))}
                </div>
                <div className="space-y-2">
                  <div className="text-xs uppercase font-semibold text-white/60">
                    Branch (optional)
                  </div>
                  <select
                    className="px-2 py-1.5 rounded bg-white/80 text-gray-800 w-full"
                    value={exportBranch}
                    onChange={(e) => setExportBranch(e.target.value)}
                  >
                    <option value="">All branches</option>
                    {branchesData.items.map((b) => (
                      <option key={b._id} value={b._id}>
                        {b.name}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2">
                  <div className="text-xs uppercase font-semibold text-white/60">
                    Format
                  </div>
                  <select
                    className="px-2 py-1.5 rounded bg-white/80 text-gray-800 w-full"
                    value={exportFormat}
                    onChange={(e) => setExportFormat(e.target.value)}
                  >
                    <option value="xlsx">Excel (.xlsx)</option>
                    <option value="pdf">PDF (single type)</option>
                  </select>
                </div>
              </div>
              <div>
                <button
                  className="px-4 py-2 rounded bg-[var(--brand)] text-white text-sm font-semibold disabled:opacity-60"
                  disabled={exporting}
                  onClick={async () => {
                    setExporting(true);
                    try {
                      const selected = Object.keys(exportTypes).filter(
                        (k) => exportTypes[k]
                      );
                      if (selected.length === 0)
                        throw new Error("Select at least one type");
                      const qs = new URLSearchParams();
                      if (selected.length === 1) qs.set("type", selected[0]);
                      else qs.set("types", selected.join(","));
                      qs.set("format", exportFormat);
                      qs.set("pharmacyId", id);
                      if (exportBranch) qs.set("branchId", exportBranch);
                      const url = `${API}/export/data?${qs.toString()}`;
                      const res = await authFetch(url, { method: "GET" });
                      if (!res.ok) {
                        const txt = await res.text();
                        throw new Error(txt || `HTTP ${res.status}`);
                      }
                      const blob = await res.blob();
                      const a = document.createElement("a");
                      const href = URL.createObjectURL(blob);
                      a.href = href;
                      const nameBase =
                        selected.length === 1
                          ? `${selected[0]}_export`
                          : "export";
                      const ext = exportFormat === "pdf" ? "pdf" : "xlsx";
                      a.download = `${nameBase}_${Date.now()}.${ext}`;
                      document.body.appendChild(a);
                      a.click();
                      a.remove();
                      URL.revokeObjectURL(href);
                    } catch (e) {
                      alert(e.message);
                    } finally {
                      setExporting(false);
                    }
                  }}
                >
                  {exporting ? "Exporting…" : "Export"}
                </button>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function TabButton({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      className={`px-3 py-1.5 rounded border text-xs font-medium tracking-wide transition ${
        active
          ? "bg-[var(--brand)] text-white border-[var(--brand)]"
          : "bg-white/10 border-white/10 hover:bg-white/20"
      }`}
    >
      {children}
    </button>
  );
}

function BigStat({ label, value, icon, onClick }) {
  const clickable = typeof onClick === "function";
  return (
    <button
      type="button"
      onClick={onClick}
      className={`p-4 rounded-xl bg-white/10 border border-white/10 flex flex-col gap-3 text-left transition ${
        clickable
          ? "hover:bg-white/15 focus:outline-none focus:ring-2 focus:ring-[var(--brand)]"
          : ""
      }`}
    >
      <div className="flex items-center justify-between text-white/60 text-[11px] uppercase font-semibold tracking-wide">
        {label}
        <span className="text-white/30">{icon}</span>
      </div>
      <div className="text-2xl font-bold">{value}</div>
    </button>
  );
}

function DrillList({ title, state, columns, rows }) {
  return (
    <div className="mt-6 space-y-4">
      <h2 className="text-lg font-semibold">{title}</h2>
      {state.loading && (
        <div className="text-white/60 text-sm">
          Loading {title.toLowerCase()}...
        </div>
      )}
      {state.error && (
        <div className="p-3 rounded bg-rose-500/15 border border-rose-500/30 text-sm text-rose-200">
          {state.error}
        </div>
      )}
      {!state.loading && !state.error && rows.length === 0 && (
        <div className="text-white/50 text-sm">
          No {title.toLowerCase()} found.
        </div>
      )}
      {rows.length > 0 && (
        <div className="overflow-auto rounded-lg border border-white/10">
          <table className="min-w-full text-sm">
            <thead className="bg-white/5 text-white/60">
              <tr>
                {columns.map((c) => (
                  <th
                    key={c}
                    className="text-left px-3 py-2 font-medium tracking-wide uppercase text-[11px]"
                  >
                    {c}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => {
                const isObj = r && typeof r === "object" && !Array.isArray(r);
                const key = isObj ? r.key || i : i;
                const cells = isObj ? r.cells : r;
                const onClick = isObj ? r.onClick : undefined;
                return (
                  <tr
                    key={key}
                    onClick={onClick}
                    className={`odd:bg-white/0 even:bg-white/[0.015] hover:bg-white/10 transition ${
                      onClick ? "cursor-pointer" : ""
                    }`}
                  >
                    {cells.map((cell, j) => (
                      <td key={j} className="px-3 py-2 whitespace-nowrap">
                        {cell}
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
